scene.fog = new THREE.FogExp2(0xddeeff, 0.015);

renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff0dd, 1.6);
keyLight.position.set(60, 120, 80);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 4096;
keyLight.shadow.mapSize.height = 4096;
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 300;
keyLight.shadow.camera.left = -100;
keyLight.shadow.camera.right = 100;
keyLight.shadow.camera.top = 100;
keyLight.shadow.camera.bottom = -100;
keyLight.shadow.bias = -0.0005;

const fillLight = new THREE.DirectionalLight(0xcce5ff, 0.7);
fillLight.position.set(-80, 60, -60);

const rimLight = new THREE.PointLight(0xaaddff, 1.2, 150);
rimLight.position.set(-40, 50, -40);

const ambientLight = new THREE.AmbientLight(0x7a8299, 0.45);
scene.add(ambientLight, keyLight, fillLight, rimLight);

function createWindowTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#0a0a15';
  ctx.fillRect(0, 0, 64, 128);
  for (let y = 4; y < 124; y += 8) {
    for (let x = 4; x < 60; x += 8) {
      if (Math.random() > 0.35) {
        const hue = Math.random() > 0.8 ? 220 : 35; 
        const sat = hue === 220 ? 80 : 90;
        const light = hue === 220 ? 60 : 55;
        ctx.fillStyle = `hsl(${hue}, ${sat}%, ${light}%)`;
        ctx.fillRect(x, y, 4, 6);
      }
    }
  }
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.magFilter = THREE.NearestFilter;
  return tex;
}

const windowTexture = createWindowTexture();
const buildingMat = new THREE.MeshStandardMaterial({
  color: 0x2a2d3a,
  roughness: 0.85,
  metalness: 0.25
});
const windowMat = new THREE.MeshStandardMaterial({
  color: 0xffaa44,
  emissive: 0xffaa44,
  emissiveMap: windowTexture,
  emissiveIntensity: 0.8,
  roughness: 0.2,
  metalness: 0.8,
  transparent: true,
  opacity: 0.95
});

const cityGroup = new THREE.Group();
scene.add(cityGroup);

const instancesMid = new THREE.InstancedMesh(new THREE.BoxGeometry(4, 1, 4), buildingMat, 120);
const instancesWinMid = new THREE.InstancedMesh(new THREE.BoxGeometry(4.1, 1, 4.1), windowMat, 120);
instancesMid.castShadow = true;
instancesMid.receiveShadow = true;
cityGroup.add(instancesMid, instancesWinMid);

const dummy = new THREE.Object3D();
const colors = [];
const colorObj = new THREE.Color();

for (let i = 0; i < 120; i++) {
  const x = (Math.random() - 0.5) * 180;
  const z = (Math.random() - 0.5) * 180;
  const h = 10 + Math.random() * 40 + (Math.abs(x) + Math.abs(z)) * 0.1;
  const scaleY = h;

  dummy.position.set(x, h / 2 - 10, z);
  dummy.scale.set(3 + Math.random() * 4, scaleY, 3 + Math.random() * 4);
  dummy.updateMatrix();
  instancesMid.setMatrixAt(i, dummy.matrix);
  instancesWinMid.setMatrixAt(i, dummy.matrix);

  if (Math.random() > 0.7) {
    colorObj.setHSL(0.6, 0.8, 0.6);
  } else {
    colorObj.setHSL(0.08, 0.9, 0.5);
  }
  colors.push(colorObj.r, colorObj.g, colorObj.b);
}

const instancesBack = new THREE.InstancedMesh(new THREE.BoxGeometry(4, 1, 4), buildingMat, 200);
const instancesWinBack = new THREE.InstancedMesh(new THREE.BoxGeometry(4.05, 1, 4.05), windowMat, 200);
cityGroup.add(instancesBack, instancesWinBack);

for (let i = 0; i < 200; i++) {
  const angle = Math.random() * Math.PI * 2;
  const radius = 60 + Math.random() * 100;
  const x = Math.cos(angle) * radius;
  const z = Math.sin(angle) * radius;
  const h = 20 + Math.random() * 60;

  dummy.position.set(x, h / 2 - 20, z);
  dummy.scale.set(4 + Math.random() * 6, h, 4 + Math.random() * 6);
  dummy.updateMatrix();
  instancesBack.setMatrixAt(i, dummy.matrix);
  instancesWinBack.setMatrixAt(i, dummy.matrix);
}

const foregroundGroup = new THREE.Group();
cityGroup.add(foregroundGroup);

for (let i = 0; i < 12; i++) {
  const w = 5 + Math.random() * 6;
  const d = 5 + Math.random() * 6;
  const h = 30 + Math.random() * 50;
  const x = (Math.random() - 0.5) * 40;
  const z = 20 + Math.random() * 30;

  const building = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), buildingMat);
  building.position.set(x, h / 2 - 5, z);
  building.castShadow = true;
  building.receiveShadow = true;

  const winGeo = new THREE.BoxGeometry(w + 0.2, h * 0.9, d + 0.2);
  const winMesh = new THREE.Mesh(winGeo, windowMat);
  winMesh.position.copy(building.position);

  if (Math.random() > 0.5) {
    const antenna = new THREE.Mesh(
      new THREE.CylinderGeometry(0.1, 0.3, 8, 8),
      new THREE.MeshStandardMaterial({ color: 0x888899, metalness: 0.9, roughness: 0.2 })
    );
    antenna.position.set(x, h / 2 + 4 - 5, z);
    foregroundGroup.add(antenna);
  }

  foregroundGroup.add(building, winMesh);
}

const trafficGeo = new THREE.ConeGeometry(0.3, 1.2, 8);
trafficGeo.rotateX(Math.PI / 2);
const trafficMat = new THREE.MeshBasicMaterial({ color: 0xff6600 });
const trafficMesh = new THREE.InstancedMesh(trafficGeo, trafficMat, 80);
cityGroup.add(trafficMesh);

const vehicles = [];
for (let i = 0; i < 80; i++) {
  const lane = Math.floor(Math.random() * 6);
  const y = 15 + lane * 8 + Math.random() * 5;
  const speed = 10 + Math.random() * 20;
  const dir = Math.random() > 0.5 ? 1 : -1;
  const x = (Math.random() - 0.5) * 200;
  const z = (Math.random() - 0.5) * 200;
  vehicles.push({ x, y, z, speed, dir, axis: Math.random() > 0.5 ? 'x' : 'z', offset: Math.random() * 100 });
}

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.maxPolarAngle = Math.PI / 2 - 0.05;
controls.minDistance = 10;
controls.maxDistance = 150;
controls.target.set(0, 10, 0);

camera.position.set(45, 35, 55);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  controls.update();

  rimLight.intensity = 1.0 + Math.sin(t * 0.8) * 0.3;

  for (let i = 0; i < vehicles.length; i++) {
    const v = vehicles[i];
    const move = v.speed * 0.02;
    if (v.axis === 'x') {
      v.x += move * v.dir;
      if (Math.abs(v.x) > 100) v.dir *= -1;
    } else {
      v.z += move * v.dir;
      if (Math.abs(v.z) > 100) v.dir *= -1;
    }
    dummy.position.set(v.x, v.y, v.z);
    dummy.scale.set(1, 1, 1);
    const rot = v.axis === 'x' ? (v.dir > 0 ? Math.PI / 2 : -Math.PI / 2) : (v.dir > 0 ? 0 : Math.PI);
    dummy.rotation.set(0, rot, 0);
    dummy.updateMatrix();
    trafficMesh.setMatrixAt(i, dummy.matrix);
  }
  trafficMesh.instanceMatrix.needsUpdate = true;

  cityGroup.rotation.y = Math.sin(t * 0.02) * 0.05;

  renderer.render(scene, camera);
}
animate();

